def wire(s):
 m=BRepBuilderAPI_MakePolygon();first=None
 for x,y in s['points']:
  p=gp_Pnt(float(x),float(y),float(s['z']));m.Add(p);first=p if first is None else first
 m.Add(first);m.Close();return m.Wire()
